class Solution {
    bool isPrime(long long x) {
        if (x <= 1) return false;
        for (long long d = 2; d * d <= x; ++d) {
            if (x % d == 0) return false;
        }
        return true;
    }

public:
    int sumOfLargestPrimes(std::string s) {
        int n = s.size();
        std::unordered_set<long long> primes;

        for (int i = 0; i < n; ++i) {
            long long val = 0;
            for (int j = i; j < n; ++j) {
                val = val * 10 + (s[j] - '0');
                if (isPrime(val)) {
                    primes.insert(val);
                }
            }
        }

        std::vector<long long> sortedPrimes(primes.begin(), primes.end());
        std::sort(sortedPrimes.rbegin(), sortedPrimes.rend());

        long long ans = 0;
        int take = std::min((int)sortedPrimes.size(), 3);
        for (int i = 0; i < take; ++i) {
            ans += sortedPrimes[i];
        }
        return (int)ans;
    }
};

import java.util.*;

class Solution {
    private boolean isPrime(long x) {
        if (x <= 1) return false;
        for (long d = 2; d * d <= x; ++d) {
            if (x % d == 0) return false;
        }
        return true;
    }

    public int sumOfLargestPrimes(String s) {
        int n = s.length();
        Set<Long> primes = new HashSet<>();

        for (int i = 0; i < n; ++i) {
            long val = 0;
            for (int j = i; j < n; ++j) {
                val = val * 10 + (s.charAt(j) - '0');
                if (isPrime(val)) {
                    primes.add(val);
                }
            }
        }

        List<Long> sortedPrimes = new ArrayList<>(primes);
        sortedPrimes.sort(Collections.reverseOrder());

        long ans = 0;
        int take = Math.min(sortedPrimes.size(), 3);
        for (int i = 0; i < take; ++i) {
            ans += sortedPrimes.get(i);
        }
        return (int) ans;
    }
}

