var sumOfLargestPrimes = function(s) {
    function isPrime(x) {
        if (x <= 1) return false;
        for (let d = 2; d * d <= x; ++d) {
            if (x % d === 0) return false;
        }
        return true;
    }

    const primes = new Set();
    const n = s.length;

    for (let i = 0; i < n; ++i) {
        let val = 0;
        for (let j = i; j < n; ++j) {
            val = val * 10 + Number(s[j]);
            if (isPrime(val)) {
                primes.add(val);
            }
        }
    }

    const sortedPrimes = Array.from(primes).sort((a, b) => b - a);
    const top3 = sortedPrimes.slice(0, 3);
    return top3.reduce((acc, curr) => acc + curr, 0);
};
